 OUT.mkdir(exist_ok=False);torch.set_num_threads(2);folder=BASE/'boundary_provenance_batch02_expanded8_v1';r=read(folder/'receipt.json');assert digest(folder/'model.pt')==r['model_sha256'];state=torch.load(folder/'model.pt',map_location='cpu',weights_only=False);model=BoundaryEventProvenanceSelector().eval();model.load_state_dict(state['state_dict']);keys=['new_cfc732e5f068','new_ceeae49d6777'];write(OUT/'protocol.json',dict(keys=keys,endpoint_model_sha256=r['model_sha256'],features='Frozen query128 + selected left event128 + right event128 + left/right normalized provenance12 each + signed query-to-left/query-to-right/carrier-length mm divided1000',columns=411,endpoint_positions='Actual frozen model argmax, no GT snaps',query_scope='All frozen balanced detector queries with expanded8 endpoint predictions; no reference selection or attribute/geometry labels read',frozen_encoder=True,attribute_label_reads=0,fit_calls=0,DEV_reads=0))
